mapper.select:
select r.id, r.customer_id, r.customer_name, r.reminder_time, r.content, r.is_read,
       r.create_time, r.creator_name
from `reminder` r
where r.organization_id = #{orgId}
and r.creator_id = #{userId}

    and r.is_read = #{request.isRead}


    and r.customer_id = #{request.customerId}

order by r.reminder_time desc, r.create_time desc
limit #{request.offset}, #{request.pageSize}

select count(*)
from `reminder` r
where r.organization_id = #{orgId}
and r.creator_id = #{userId}
and r.is_read = false
